import {STAGES,KEY,money,compactMoney,dateKey,offsetDate,seed,stats,moveDeal,validateBackup} from './model.js';
const $ = s => document.querySelector(s);
const esc = s => String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icons={grid:'M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z',people:'M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2 M9 11a4 4 0 1 0 0-8 4 4 0 0 0 0 8 M22 21v-2a4 4 0 0 0-3-3.87 M16 3.13a4 4 0 0 1 0 7.75',target:'M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0 M17 12a5 5 0 1 1-10 0 5 5 0 0 1 10 0 M12 10v4 M10 12h4',board:'M3 4h18v16H3z M9 4v16 M15 4v16',check:'M9 11l3 3L22 4 M21 12v8H3V4h12',chart:'M3 3v18h18 M7 15v-4 M12 15V7 M17 15V5',book:'M12 5v16 M12 5C8 2 4 3 2 4v15c4-1 7-1 10 2 3-3 6-3 10-2V4c-3-1-7-2-10 1',settings:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8 M9 3h6l1 3 3 1 2 5-2 5-3 1-1 3H9l-1-3-3-1-2-5 2-5 3-1z',search:'M21 21l-5-5 M18 10a8 8 0 1 1-16 0 8 8 0 0 1 16 0',plus:'M12 5v14 M5 12h14',arrow:'M5 12h14 M13 6l6 6-6 6',up:'M7 17L17 7 M7 7h10v10',download:'M12 3v12 M7 10l5 5 5-5 M5 16v5h14v-5',clock:'M12 8v4l3 2 M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0',more:'M5 12h.01 M12 12h.01 M19 12h.01',close:'M6 6l12 12 M18 6L6 18',mail:'M3 5h18v14H3z M3 5l9 7 9-7',phone:'M5 3h4l2 5-3 2a16 16 0 0 0 6 6l2-3 5 2v4c0 2-3 2-5 1C9 17 4 12 3 5c0-1 0-2 2-2',building:'M4 21V3h12v18 M16 9h4v12 M8 7h4 M8 11h4 M8 15h4 M2 21h20',wallet:'M3 5h16v4 M3 5v14h18V9H3 M16 14h2',menu:'M3 6h18 M3 12h18 M3 18h18',shield:'M12 3l8 3v6c0 5-8 9-8 9s-8-4-8-9V6z M8 12l3 3 5-6',spark:'M12 3l2.5 6.5L21 12l-6.5 2.5L12 21l-2.5-6.5L3 12l6.5-2.5z',edit:'M15 5l4 4 M4 20l4-1L21 6l-4-4L4 15z',trash:'M3 6h18 M9 6V3h6v3 M5 6l1 15h12l1-15 M10 10v7 M14 10v7'};
const icon=(name,cls='')=>`<svg class="icon ${cls}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${icons[name]||icons.grid}"/></svg>`;
let data; let storageError=false;
try {const raw=localStorage.getItem(KEY);data=raw?validateBackup(JSON.parse(raw)):seed();} catch {data=seed();storageError=true;}
let page=location.hash.slice(1)||'dashboard',query='',filter='Semua',days=30,taskFilter='Aktif',mobile=false;
const nav=[['dashboard','grid','Dashboard'],['contacts','people','Kontak'],['leads','target','Leads'],['pipeline','board','Pipeline'],['tasks','check','Tugas'],['reports','chart','Laporan']];
const titles={dashboard:['Dashboard','Gambaran bisnis Anda, dalam satu tempat.'],contacts:['Kontak','Bangun hubungan yang lebih baik dengan setiap klien.'],leads:['Leads','Dari percakapan pertama menjadi peluang baru.'],pipeline:['Pipeline penjualan','Setiap peluang punya langkah berikutnya.'],tasks:['Tugas & follow-up','Jaga percakapan berjalan. Jangan lewatkan kesempatan.'],reports:['Laporan penjualan','Pahami angka di balik perkembangan bisnis Anda.'],guide:['Panduan CRM','Belajar konsepnya, lalu praktikkan langsung.'],settings:['Pengaturan','Kelola workspace dan data demo Anda.']};
function save(message){try{localStorage.setItem(KEY,JSON.stringify(data));storageError=false;}catch{storageError=true;toast('Penyimpanan tidak tersedia. Perubahan hanya bertahan selama halaman ini terbuka.');}render();if(message&&!storageError)toast(message);}
function log(text){data.activities.unshift({id:crypto.randomUUID(),text,date:new Date().toISOString()});data.activities=data.activities.slice(0,60);}
function toast(text){$('#toast').textContent=text;$('#toast').classList.add('visible');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('visible'),4500);}
function contact(id){return data.contacts.find(c=>c.id===id)||{name:'Tanpa kontak',company:'—'};}
const initials=name=>String(name).trim().split(/\s+/).slice(0,2).map(w=>w[0]||'').join('').toUpperCase();
function avatar(c,i=0){return `<span class="avatar tone-${i%5}">${esc(initials(c.name))}</span>`;}
function badge(text){return `<span class="badge badge-${['Berhasil','Dikonversi','Selesai'].includes(text)?'green':['Gagal','Tinggi','Tidak cocok'].includes(text)?'red':['Proposal','Kualifikasi','Sedang'].includes(text)?'amber':['Negosiasi','Dihubungi'].includes(text)?'purple':'blue'}">${esc(text)}</span>`;}
function fmtDate(s){return s?new Date(s+'T12:00:00').toLocaleDateString('id-ID',{day:'numeric',month:'short'}):'—';}
function matches(...values){return values.some(v=>String(v||'').toLowerCase().includes(query.toLowerCase()));}
function empty(title,description,action=''){return `<div class="empty">${icon('search')}<h3>${title}</h3><p>${description}</p>${action}</div>`;}
function actionButton(kind,label){return `<button class="btn primary" data-action="new" data-kind="${kind}">${icon('plus')}${label}</button>`;}
function dateSelect(){return `<select id="period" aria-label="Periode laporan">${[30,90,365].map(d=>`<option value="${d}" ${days===d?'selected':''}>${d} hari terakhir</option>`).join('')}</select>`;}
function render(){
  if(!titles[page])page='dashboard';
  const [title,sub]=titles[page];
  $('#app').innerHTML=`<aside class="sidebar ${mobile?'open':''}"><a class="brand" href="#dashboard"><span class="brand-mark">${icon('grid')}</span><span>crm<span class="brand-light">business</span><small>SALES WORKSPACE</small></span></a><button class="workspace" data-action="navigate" data-page="settings"><span class="workspace-icon">N</span><span><strong>${esc(data.workspace)}</strong><small>Personal workspace</small></span><span class="chevron">⌄</span></button><p class="nav-label">WORKSPACE</p><nav aria-label="Navigasi utama">${nav.map(([key,ic,label])=>`<a href="#${key}" class="nav-item ${page===key?'active':''}">${icon(ic)}<span>${label}</span>${key==='tasks'?`<span class="nav-count">${data.tasks.filter(t=>!t.done).length}</span>`:''}</a>`).join('')}</nav><p class="nav-label resources-label">RESOURCES</p><a class="nav-item ${page==='guide'?'active':''}" href="#guide">${icon('book')}Panduan CRM<span class="tiny-new">NEW</span></a><a class="nav-item ${page==='settings'?'active':''}" href="#settings">${icon('settings')}Pengaturan</a><div class="sidebar-bottom"><div class="demo-card">${icon('spark')}<strong>Your next big deal starts here.</strong><p>Pelajari alurnya. Bangun relasinya.</p><a href="#guide">Kenali CRM ${icon('arrow')}</a></div><div class="profile"><span class="avatar profile-avatar">NS</span><div><strong>Portfolio workspace</strong><small>Demo · data fiktif</small></div><span class="online-dot"></span></div></div></aside><div class="main-shell"><header class="topbar"><div class="crumb"><button class="icon-btn mobile-toggle" data-action="menu" aria-label="Buka navigasi">${icon('menu')}</button><span>Workspace</span><span class="crumb-slash">/</span><strong>${title}</strong></div><div class="topbar-right"><span class="demo-pill"><span></span>Portfolio demo</span><a class="help-button" href="#guide" aria-label="Buka panduan CRM">?</a><span class="avatar mini">NS</span></div></header><main><div class="page-heading"><div><div class="eyebrow">${page==='dashboard'?'YOUR BUSINESS AT A GLANCE':'NUSANTARA SALES WORKSPACE'}</div><h1>${title}${page==='dashboard'?'<span class="hello-dot">.</span>':''}</h1><p>${sub}</p></div><div class="heading-actions">${['dashboard','reports'].includes(page)?dateSelect():''}${page==='dashboard'||page==='pipeline'?actionButton('deals','Tambah deal'):page==='contacts'?actionButton('contacts','Tambah kontak'):page==='leads'?actionButton('leads','Tambah lead'):page==='tasks'?actionButton('tasks','Tambah tugas'):''}</div></div>${storageError?'<div class="warning">Penyimpanan browser tidak tersedia atau data sebelumnya tidak valid. Ekspor backup sebelum meninggalkan halaman.</div>':''}<div id="page-content">${({dashboard,contacts:contactsPage,leads:leadsPage,pipeline:pipelinePage,tasks:tasksPage,reports:reportsPage,guide:guidePage,settings:settingsPage}[page])()}</div><footer><span>CRM Business <span class="footer-dot">·</span> Made for meaningful relationships</span><span>${icon('shield')} Data disimpan di browser Anda</span></footer></main></div>`;
  bindPage();
}
function metrics(){const s=stats(data,days);return `<div class="metrics">${[
  ['wallet','Deal berhasil',compactMoney(s.won),`${s.wonCount} deal dalam ${days} hari`,'green'],
  ['board','Nilai pipeline',compactMoney(s.pipeline),`${s.activeCount} peluang penjualan aktif`,'blue'],
  ['people','Total kontak',data.contacts.length,`${new Set(data.contacts.map(c=>c.company).filter(Boolean)).size} perusahaan dalam jaringan`,'purple'],
  ['target','Win rate',`${s.winRate}%`,`${s.wonCount} berhasil dari ${s.closedCount} deal ditutup`,'amber']
].map(([ic,label,value,hint,tone])=>`<section class="metric"><div class="metric-top"><span>${label}</span><span class="metric-icon ${tone}">${icon(ic)}</span></div><strong>${value}</strong><div class="metric-hint">${icon(tone==='green'?'up':'clock')} ${hint}</div></section>`).join('')}</div>`;}
function chart(){
  const now=new Date();const months=Array.from({length:6},(_,i)=>new Date(now.getFullYear(),now.getMonth()-5+i,1));
  const values=months.map(m=>data.deals.filter(d=>d.stage==='Berhasil'&&d.closed&&d.closed.slice(0,7)===dateKey(m).slice(0,7)).reduce((s,d)=>s+d.value,0));
  const max=Math.max(...values,10000000);const points=values.map((v,i)=>[52+i*106,175-v/max*140]);
  const line=points.map((p,i)=>(i?'L':'M')+p.join(',')).join(' ');
  return `<div class="chart-wrap"><svg class="revenue-chart" viewBox="0 0 650 222" role="img" aria-label="Grafik nilai deal berhasil selama enam bulan"><defs><linearGradient id="area" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stop-color="#3b82f6" stop-opacity=".17"/><stop offset="100%" stop-color="#3b82f6" stop-opacity="0"/></linearGradient></defs>${[0,.5,1].map(r=>`<line x1="52" y1="${175-r*140}" x2="610" y2="${175-r*140}" stroke="#e9edf3" stroke-dasharray="4 5"/><text x="4" y="${180-r*140}" fill="#909bad" font-size="11">${r?Math.round(max*r/1e6)+' jt':'0'}</text>`).join('')}<path d="${line} L582,175 L52,175 Z" fill="url(#area)"/><path d="${line}" fill="none" stroke="#3b82f6" stroke-width="3" stroke-linejoin="round"/>${points.map(([x,y],i)=>`<circle cx="${x}" cy="${y}" r="4" fill="white" stroke="#3b82f6" stroke-width="2"><title>${months[i].toLocaleDateString('id-ID',{month:'long'})}: ${money(values[i])}</title></circle><text x="${x}" y="211" text-anchor="middle" fill="#8792a5" font-size="12">${months[i].toLocaleDateString('id-ID',{month:'short'})}</text>`).join('')}</svg></div>`;
}
function stageSummary(){const active=STAGES.slice(0,4);const total=stats(data).pipeline||1;return `<div class="stage-summary">${active.map((st,i)=>{const list=data.deals.filter(d=>d.stage===st);const value=list.reduce((s,d)=>s+d.value,0);return `<div><div class="stage-row"><span><i class="stage-dot s${i}"></i>${st}<small>${list.length}</small></span><strong>${compactMoney(value)}</strong></div><div class="progress"><span class="s${i}" style="width:${value/total*100}%"></span></div></div>`;}).join('')}</div>`;}
function dashboard(){const pending=data.tasks.filter(t=>!t.done).sort((a,b)=>a.date.localeCompare(b.date)).slice(0,4);return `${metrics()}<div class="dashboard-middle"><section class="panel revenue-panel"><div class="panel-heading"><div><h2>Performa penjualan</h2><p>Nilai deal berhasil · 6 bulan terakhir</p></div><span class="legend"><i></i>Deal berhasil</span></div>${chart()}</section><section class="panel"><div class="panel-heading"><div><h2>Pipeline overview</h2><p>Peluang yang sedang berjalan</p></div><a href="#pipeline" class="icon-link" aria-label="Lihat pipeline">${icon('up')}</a></div>${stageSummary()}<a href="#pipeline" class="panel-bottom-link">Lihat semua peluang ${icon('arrow')}</a></section></div><div class="dashboard-bottom"><section class="panel deal-panel"><div class="panel-heading"><div><h2>Peluang terbaru <span class="count-label">${data.deals.length}</span></h2><p>Satu langkah lebih dekat ke deal berikutnya</p></div><a href="#pipeline" class="text-link">Lihat semua ${icon('arrow')}</a></div>${dealTable(data.deals.slice().sort((a,b)=>b.created.localeCompare(a.created)).slice(0,4))}</section><section class="panel follow-panel"><div class="panel-heading"><div><h2>Agenda follow-up</h2><p>${data.tasks.filter(t=>!t.done&&t.date===dateKey()).length} tugas hari ini · tetap terhubung</p></div><a href="#tasks" class="icon-link" aria-label="Lihat semua tugas">${icon('up')}</a></div>${pending.length?pending.map(taskItem).join(''):empty('Semua beres!','Tidak ada follow-up yang tertunda.')}<a href="#tasks" class="panel-bottom-link">Lihat semua tugas ${icon('arrow')}</a></section></div><div class="learn-banner"><span class="learn-icon">${icon('book')}</span><div><strong>Baru mengenal CRM? Mulai dari satu hubungan.</strong><p>Kenali leads, contacts, dan deals lewat panduan singkat kami.</p></div><a href="#guide">Buka panduan ${icon('arrow')}</a></div>`;}
function dealTable(list){return list.length?`<div class="table-wrap"><table><thead><tr><th>PELUANG / PERUSAHAAN</th><th>NILAI DEAL</th><th>TAHAP</th><th aria-label="Aksi"></th></tr></thead><tbody>${list.map((d,i)=>`<tr><td><button class="row-person" data-action="edit" data-kind="deals" data-id="${esc(d.id)}">${avatar(contact(d.contact),i)}<span><strong>${esc(d.title)}</strong><small>${esc(contact(d.contact).company)}</small></span></button></td><td class="numeric">${money(d.value)}</td><td>${badge(d.stage)}</td><td><button class="icon-btn" data-action="edit" data-kind="deals" data-id="${esc(d.id)}" aria-label="Edit ${esc(d.title)}">${icon('more')}</button></td></tr>`).join('')}</tbody></table></div>`:empty('Belum ada peluang','Tambahkan deal pertama Anda.',actionButton('deals','Tambah deal'));}
function taskItem(t){const overdue=t.date<dateKey()&&!t.done;return `<div class="task-item ${t.done?'completed':''}"><input type="checkbox" data-task="${esc(t.id)}" ${t.done?'checked':''} aria-label="Selesaikan ${esc(t.title)}"><button class="task-text" data-action="edit" data-kind="tasks" data-id="${esc(t.id)}"><strong>${esc(t.title)}</strong><small>${esc(contact(t.contact).company)} <span>·</span> <span class="${overdue?'overdue':''}">${t.date===dateKey()?'Hari ini':fmtDate(t.date)}${overdue?' · Terlewat':''}</span></small></button><span class="priority-dot ${t.priority==='Tinggi'?'high':t.priority==='Sedang'?'medium':'low'}" title="Prioritas ${esc(t.priority)}"></span></div>`;}
function toolbar(filters,extra=''){return `<div class="toolbar"><label class="search-box">${icon('search')}<input id="search" type="search" value="${esc(query)}" placeholder="Cari ${page==='contacts'?'nama, perusahaan, email':page==='pipeline'?'peluang atau perusahaan':page==='leads'?'lead atau perusahaan':'tugas atau perusahaan'}…" aria-label="Cari data"></label><div class="toolbar-right">${filters?`<select id="filter" aria-label="Filter data">${filters.map(s=>`<option ${filter===s?'selected':''}>${s}</option>`).join('')}</select>`:''}${extra}</div></div>`;}
function contactsPage(){const list=data.contacts.filter(c=>matches(c.name,c.company,c.email));return `${toolbar(null,`<button class="btn" data-action="csv">${icon('download')}Ekspor CSV</button>`)}<section class="panel"><div class="panel-heading"><h2>Semua kontak <span class="count-label">${list.length}</span></h2><span class="muted">${new Set(data.contacts.map(c=>c.company).filter(Boolean)).size} perusahaan</span></div>${list.length?`<div class="table-wrap"><table><thead><tr><th>NAMA KONTAK</th><th>PERUSAHAAN</th><th>EMAIL</th><th>TELEPON</th><th>DEAL</th><th></th></tr></thead><tbody>${list.map((c,i)=>`<tr><td><button class="row-person" data-action="edit" data-kind="contacts" data-id="${esc(c.id)}">${avatar(c,i)}<span><strong>${esc(c.name)}</strong><small>${esc(c.role||'Kontak bisnis')}</small></span></button></td><td>${esc(c.company||'—')}</td><td class="muted">${esc(c.email||'—')}</td><td class="muted">${esc(c.phone||'—')}</td><td><span class="count-label">${data.deals.filter(d=>d.contact===c.id).length}</span></td><td><button class="icon-btn" data-action="edit" data-kind="contacts" data-id="${esc(c.id)}" aria-label="Edit ${esc(c.name)}">${icon('edit')}</button></td></tr>`).join('')}</tbody></table></div>`:empty('Tidak ada kontak','Coba kata pencarian lain atau tambahkan kontak baru.',actionButton('contacts','Tambah kontak'))}</section>`;}
function leadsPage(){const list=data.leads.filter(l=>matches(l.name,l.company,l.email)&&(filter==='Semua'||filter===l.status));return `${toolbar(['Semua','Baru','Dihubungi','Kualifikasi','Dikonversi','Tidak cocok'])}<div class="info-strip">${icon('target')}<span><strong>Lead adalah awal sebuah hubungan.</strong> Setelah kebutuhannya jelas, konversikan menjadi kontak dan peluang penjualan.</span></div><section class="panel"><div class="panel-heading"><h2>Daftar leads <span class="count-label">${list.length}</span></h2></div>${list.length?`<div class="table-wrap"><table><thead><tr><th>CALON KLIEN</th><th>SUMBER</th><th>STATUS</th><th>DITAMBAHKAN</th><th>AKSI</th></tr></thead><tbody>${list.map((l,i)=>`<tr><td><button class="row-person" data-action="edit" data-kind="leads" data-id="${esc(l.id)}">${avatar(l,i)}<span><strong>${esc(l.name)}</strong><small>${esc(l.company)}</small></span></button></td><td>${esc(l.source)}</td><td>${badge(l.status)}</td><td class="muted">${fmtDate(l.created)}</td><td>${l.status==='Dikonversi'?'<span class="muted">Sudah dikonversi</span>':`<button class="btn small" data-action="convert" data-id="${esc(l.id)}">Konversi ${icon('arrow')}</button>`}</td></tr>`).join('')}</tbody></table></div>`:empty('Tidak ada lead','Tambahkan calon pelanggan pertama Anda.',actionButton('leads','Tambah lead'))}</section>`;}
function pipelinePage(){const stages=filter==='Semua'?STAGES:[filter];return `${toolbar(['Semua',...STAGES])}<div class="pipeline-stats"><span><strong>${stats(data).activeCount}</strong> deal aktif</span><span><strong>${compactMoney(stats(data).pipeline)}</strong> nilai pipeline</span><span class="muted">Geser kartu atau ubah tahap di dalam kartu</span></div><div class="kanban">${stages.map(st=>{const list=data.deals.filter(d=>d.stage===st&&matches(d.title,contact(d.contact).company,contact(d.contact).name));return `<section class="kanban-column" data-stage="${st}"><div class="column-heading"><span><i class="stage-dot s${STAGES.indexOf(st)}"></i><strong>${st}</strong><small>${list.length}</small></span><button class="icon-btn" data-action="new" data-kind="deals" data-stage="${st}" aria-label="Tambah deal tahap ${st}">${icon('plus')}</button></div><div class="column-total">${compactMoney(list.reduce((s,d)=>s+d.value,0))}</div><div class="drop-zone">${list.map(d=>`<article class="deal-card" draggable="true" data-deal="${esc(d.id)}"><div class="deal-card-top"><span class="company-label">${esc(contact(d.contact).company)}</span><button class="icon-btn" data-action="edit" data-kind="deals" data-id="${esc(d.id)}" aria-label="Edit ${esc(d.title)}">${icon('more')}</button></div><button class="deal-title" data-action="edit" data-kind="deals" data-id="${esc(d.id)}">${esc(d.title)}</button><strong class="deal-value">${money(d.value)}</strong><div class="deal-card-footer"><span>${avatar(contact(d.contact),STAGES.indexOf(st))}${esc(contact(d.contact).name.split(' ')[0])}</span><span>${icon('clock')}${fmtDate(d.due)}</span></div><select class="stage-select" data-move="${esc(d.id)}" aria-label="Tahap ${esc(d.title)}">${STAGES.map(s=>`<option ${st===s?'selected':''}>${s}</option>`).join('')}</select></article>`).join('')||'<div class="drop-empty">Belum ada deal<br><small>Tambahkan atau geser kartu ke sini</small></div>'}</div></section>`;}).join('')}</div>`;}
function tasksPage(){const list=data.tasks.filter(t=>matches(t.title,contact(t.contact).company)&&(taskFilter==='Semua'||(taskFilter==='Selesai'?t.done:!t.done))).sort((a,b)=>a.date.localeCompare(b.date));return `${toolbar(null)}<div class="tabs" role="group" aria-label="Filter tugas">${['Aktif','Selesai','Semua'].map(f=>`<button class="${taskFilter===f?'selected':''}" data-action="task-filter" data-filter="${f}">${f}<span>${data.tasks.filter(t=>f==='Semua'||(f==='Selesai'?t.done:!t.done)).length}</span></button>`).join('')}</div><section class="panel task-list"><div class="panel-heading"><div><h2>Langkah berikutnya</h2><p>Tandai tugas ketika follow-up sudah dilakukan.</p></div>${badge(`${data.tasks.filter(t=>!t.done&&t.date<dateKey()).length} terlewat`)}</div>${list.length?list.map(taskItem).join(''):empty('Agenda bersih','Tidak ada tugas pada filter ini.',actionButton('tasks','Tambah tugas'))}</section>`;}
function reportsPage(){const s=stats(data,days);return `${metrics()}<div class="dashboard-middle"><section class="panel"><div class="panel-heading"><div><h2>Tren deal berhasil</h2><p>Nilai kontrak, bukan pembayaran yang diterima</p></div></div>${chart()}</section><section class="panel"><div class="panel-heading"><div><h2>Distribusi pipeline</h2><p>Nilai peluang per tahap aktif</p></div></div>${stageSummary()}</section></div><div class="dashboard-bottom"><section class="panel"><div class="panel-heading"><div><h2>Sumber leads</h2><p>Seluruh lead yang tercatat</p></div></div><div class="source-list">${[...new Set(data.leads.map(l=>l.source))].map((src,i)=>`<div class="source-row"><span><i class="stage-dot s${i%4}"></i>${esc(src)}</span><div class="progress"><span class="s${i%4}" style="width:${data.leads.filter(l=>l.source===src).length/Math.max(data.leads.length,1)*100}%"></span></div><strong>${data.leads.filter(l=>l.source===src).length}</strong></div>`).join('')||empty('Belum ada lead','Tambahkan lead untuk melihat sumbernya.')}</div></section><section class="panel"><div class="panel-heading"><h2>Ringkasan ${days} hari</h2></div><dl class="report-summary"><div><dt>Deal berhasil</dt><dd>${s.wonCount}</dd></div><div><dt>Deal gagal</dt><dd>${s.closedCount-s.wonCount}</dd></div><div><dt>Rata-rata nilai deal berhasil</dt><dd>${compactMoney(s.wonCount?s.won/s.wonCount:0)}</dd></div><div><dt>Win rate</dt><dd>${s.winRate}%</dd></div></dl></section></div><section class="panel"><div class="panel-heading"><h2>Aktivitas terbaru</h2></div><div class="activity-list">${data.activities.slice(0,8).map(a=>`<div>${icon('clock')}<span>${esc(a.text)}</span><small>${new Date(a.date).toLocaleDateString('id-ID',{day:'numeric',month:'short'})}</small></div>`).join('')||'<p class="muted">Belum ada aktivitas.</p>'}</div></section>`;}
function guidePage(){return `<section class="guide-hero"><span class="eyebrow">RELATIONSHIPS FIRST</span><h2>Kenali pelanggan.<br>Temukan peluang.<br><span>Tumbuh bersama.</span></h2><p>CRM membantu Anda mengelola hubungan pelanggan: siapa mereka, apa yang mereka butuhkan, dan kapan Anda perlu menghubungi mereka kembali.</p><a class="btn primary" href="#leads">Mulai dari lead pertama ${icon('arrow')}</a><div class="guide-graphic" aria-hidden="true"><span>${icon('people')}</span><span>${icon('target')}</span><span>${icon('board')}</span></div></section><div class="guide-grid">${[['01','Lead','Calon pelanggan yang baru menunjukkan minat. Catat sumber dan kebutuhannya sebelum menilai kecocokan.','leads'],['02','Contact & Company','Contact adalah orang yang Anda hubungi; company adalah perusahaan tempat ia bekerja. Di demo ini, perusahaan dicatat pada kontak.','contacts'],['03','Deal & Pipeline','Deal adalah peluang penjualan dengan nilai dan target tanggal. Pipeline menunjukkan kemajuannya dari baru sampai berhasil atau gagal.','pipeline'],['04','Activity & Follow-up','Catat langkah berikutnya sebagai tugas. Follow-up menjaga komunikasi dan membantu peluang terus bergerak.','tasks']].map(([n,t,d,p])=>`<section class="panel guide-card"><span class="guide-number">${n}</span><h3>${t}</h3><p>${d}</p><a href="#${p}" class="text-link">Coba sekarang ${icon('arrow')}</a></section>`).join('')}</div><section class="panel walkthrough"><h2>Coba satu alur CRM lengkap</h2><ol><li>Tambahkan lead dari perusahaan yang tertarik membuat website.</li><li>Ubah status menjadi Kualifikasi setelah kebutuhan dan anggarannya jelas.</li><li>Klik Konversi: kontak dibuat dan formulir deal terbuka.</li><li>Isi nilai penawaran dan gerakkan deal lewat Proposal serta Negosiasi.</li><li>Buat tugas follow-up, lalu tandai deal Berhasil ketika kontrak disepakati.</li></ol><p class="muted">Win rate = deal berhasil ÷ seluruh deal yang ditutup pada periode pilihan. Nilai deal berhasil tidak berarti uang sudah diterima.</p></section>`;}
function settingsPage(){return `<div class="settings-grid"><section class="panel settings-panel"><h2>Workspace Anda</h2><p class="muted">Nama ini tampil di sidebar aplikasi.</p><form id="workspace-form"><label>Nama workspace<input name="workspace" value="${esc(data.workspace)}" required maxlength="80"></label><button class="btn primary" type="submit">Simpan perubahan</button></form><div class="storage-note">${icon('shield')}<div><strong>Mode demo lokal</strong><p>Data tersimpan di browser ini. Tidak disinkronkan ke perangkat lain, dan tidak ada autentikasi pengguna. Gunakan data fiktif untuk portfolio.</p></div></div></section><section class="panel settings-panel"><h2>Data & backup</h2><p class="muted">Simpan salinan data Anda atau kembalikan data demo.</p><div class="setting-action"><div><strong>Ekspor backup</strong><small>Semua kontak, leads, deals, dan tugas dalam JSON.</small></div><button class="btn" data-action="backup">${icon('download')}Ekspor</button></div><div class="setting-action"><div><strong>Impor backup</strong><small>Mengganti data saat ini dengan backup yang valid.</small></div><button class="btn" data-action="import">Impor JSON</button><input type="file" id="import-file" accept=".json,application/json" hidden></div><div class="setting-action"><div><strong>Reset data demo</strong><small>Hapus perubahan dan pulihkan contoh bawaan.</small></div><button class="btn danger" data-action="reset">Reset demo</button></div></section></div><div class="info-strip">${icon('book')}<span>Versi portfolio ini tidak memerlukan API eksternal. Database, login, dan sinkronisasi tim dapat ditambahkan sebagai tahap pengembangan berikutnya.</span></div>`;}
function navigate(p){if(location.hash==='#'+p){page=p;query='';filter='Semua';mobile=false;render();}else location.hash=p;}
window.addEventListener('hashchange',()=>{page=location.hash.slice(1);query='';filter='Semua';mobile=false;render();window.scrollTo(0,0);});
function bindPage(){
  $('#period')?.addEventListener('change',e=>{days=Number(e.target.value);render();});
  $('#search')?.addEventListener('input',e=>{const pos=e.target.selectionStart;query=e.target.value;render();$('#search').focus();try{$('#search').setSelectionRange(pos,pos);}catch{}});
  $('#filter')?.addEventListener('change',e=>{filter=e.target.value;render();});
  document.querySelectorAll('[data-task]').forEach(el=>el.addEventListener('change',()=>{const t=data.tasks.find(t=>t.id===el.dataset.task);t.done=el.checked;log(`${t.done?'Tugas selesai':'Tugas dibuka kembali'}: ${t.title}`);save(t.done?'Tugas selesai. Kerja bagus!':'Tugas kembali aktif.');}));
  document.querySelectorAll('[data-move]').forEach(el=>el.addEventListener('change',()=>changeStage(el.dataset.move,el.value)));
  document.querySelectorAll('[draggable]').forEach(el=>el.addEventListener('dragstart',e=>{e.dataTransfer.setData('text/plain',el.dataset.deal);e.dataTransfer.effectAllowed='move';}));
  document.querySelectorAll('[data-stage].kanban-column').forEach(el=>{el.addEventListener('dragover',e=>{e.preventDefault();el.classList.add('drag-over');});el.addEventListener('dragleave',()=>el.classList.remove('drag-over'));el.addEventListener('drop',e=>{e.preventDefault();el.classList.remove('drag-over');changeStage(e.dataTransfer.getData('text/plain'),el.dataset.stage);});});
  $('#workspace-form')?.addEventListener('submit',e=>{e.preventDefault();const name=new FormData(e.target).get('workspace').trim();if(!name)return;data.workspace=name;save('Nama workspace diperbarui.');});
  $('#import-file')?.addEventListener('change',async e=>{const file=e.target.files[0];if(!file)return;if(file.size>5e6){toast('Backup maksimal 5 MB.');return;}try{const imported=validateBackup(JSON.parse(await file.text()));confirmModal('Impor backup?','Data saat ini akan diganti. Ekspor backup terlebih dahulu jika masih diperlukan.',()=>{data=imported;save('Backup berhasil diimpor.');});}catch(err){toast(err.message||'Backup tidak valid.');}});
}
function changeStage(id,stage){if(moveDeal(data,id,stage)){log(`Deal ${data.deals.find(d=>d.id===id).title} berpindah ke ${stage}`);save(`Deal dipindahkan ke ${stage}.`);}}
document.addEventListener('click',e=>{const el=e.target.closest('[data-action]');if(!el)return;const {action,kind,id}=el.dataset;
  if(action==='new')openForm(kind,null,{stage:el.dataset.stage});
  if(action==='edit')openForm(kind,id);
  if(action==='navigate')navigate(el.dataset.page);
  if(action==='menu'){mobile=!mobile;render();}
  if(action==='task-filter'){taskFilter=el.dataset.filter;render();}
  if(action==='close')$('#modal').close();
  if(action==='delete')deleteItem(kind,id);
  if(action==='convert')convertLead(id);
  if(action==='csv')exportCsv();
  if(action==='backup')download('crm-business-backup.json',JSON.stringify(data,null,2),'application/json');
  if(action==='import')$('#import-file').click();
  if(action==='reset')confirmModal('Reinisialisasi data demo?','Semua perubahan pada browser ini akan diganti dengan data contoh. Tindakan ini tidak bisa dibatalkan.',()=>{data=seed();save('Data demo berhasil dipulihkan.');});
});
const names={contacts:'kontak',leads:'lead',deals:'deal',tasks:'tugas'};
function input(label,name,value='',type='text',required=false,extra=''){return `<label>${label}${required?' <span class="required">*</span>':''}<input name="${name}" type="${type}" value="${esc(value)}" ${required?'required':''} ${extra} maxlength="200"></label>`;}
function select(label,name,options,value,required=false){return `<label>${label}${required?' <span class="required">*</span>':''}<select name="${name}" ${required?'required':''}>${options.map(o=>{const [v,t]=Array.isArray(o)?o:[o,o];return `<option value="${esc(v)}" ${v===value?'selected':''}>${esc(t)}</option>`;}).join('')}</select></label>`;}
function openForm(kind,id=null,defaults={}){
  const item=id?data[kind].find(r=>r.id===id):{};if(!item)return;
  const v={...defaults,...item};let fields='';
  if(kind==='contacts')fields=input('Nama lengkap','name',v.name,'text',true)+input('Perusahaan','company',v.company)+input('Email','email',v.email,'email')+input('Telepon','phone',v.phone,'tel')+input('Jabatan','role',v.role);
  if(kind==='leads')fields=input('Nama lengkap','name',v.name,'text',true)+input('Perusahaan','company',v.company)+input('Email','email',v.email,'email')+select('Sumber lead','source',['Website','Instagram','LinkedIn','Referral','Event','Lainnya'],v.source||'Website')+select('Status','status',v.status==='Dikonversi'?['Dikonversi']:['Baru','Dihubungi','Kualifikasi','Tidak cocok'],v.status||'Baru')+`<label class="full">Kebutuhan / catatan<textarea name="notes" rows="3" maxlength="5000">${esc(v.notes)}</textarea></label>`;
  if(kind==='deals')fields=input('Nama peluang','title',v.title,'text',true)+select('Kontak terkait','contact',[['','Pilih kontak'],...data.contacts.map(c=>[c.id,`${c.name} · ${c.company}`])],v.contact||'',true)+input('Nilai penawaran (Rp)','value',v.value??'','number',true,'min="0" max="1000000000000" step="1"')+select('Tahap','stage',STAGES,v.stage||'Baru')+input('Target penutupan','due',v.due||offsetDate(14),'date',true)+`<label class="full">Catatan deal<textarea name="notes" rows="3" maxlength="5000">${esc(v.notes)}</textarea></label>`;
  if(kind==='tasks')fields=input('Judul tugas','title',v.title,'text',true)+select('Kontak terkait','contact',[['','Tanpa kontak'],...data.contacts.map(c=>[c.id,`${c.name} · ${c.company}`])],v.contact||'')+input('Tanggal follow-up','date',v.date||dateKey(),'date',true)+select('Prioritas','priority',['Rendah','Sedang','Tinggi'],v.priority||'Sedang');
  $('#modal').innerHTML=`<div class="modal-heading"><div><span class="eyebrow">YOUR NEXT CONNECTION</span><h2 id="modal-title">${id?'Edit':'Tambah'} ${names[kind]}</h2></div><button class="icon-btn" data-action="close" aria-label="Tutup formulir">${icon('close')}</button></div><form id="record-form"><div class="form-grid">${fields}</div><p class="form-help">${kind==='deals'&&!data.contacts.length?'Tambahkan kontak terlebih dahulu sebelum membuat deal.':'* Wajib diisi. Data tersimpan hanya di browser ini.'}</p><div class="modal-actions">${id?`<button type="button" class="btn danger delete-button" data-action="delete" data-kind="${kind}" data-id="${esc(id)}">${icon('trash')}Hapus</button>`:''}<button type="button" class="btn" data-action="close">Batal</button><button class="btn primary" type="submit">${id?'Simpan perubahan':`Tambah ${names[kind]}`}</button></div></form>`;
  if(!$('#modal').open)$('#modal').showModal();
  $('#record-form').addEventListener('submit',e=>{
    e.preventDefault();const values=Object.fromEntries(new FormData(e.target));Object.keys(values).forEach(k=>values[k]=values[k].trim());
    if(!(values.name||values.title)){toast('Nama atau judul tidak boleh kosong.');return;}
    if(kind==='deals'){values.value=Number(values.value);if(!Number.isFinite(values.value)||values.value<0||!data.contacts.some(c=>c.id===values.contact)){toast('Periksa nilai dan kontak deal.');return;}values.created=v.created||dateKey();values.closed=['Berhasil','Gagal'].includes(values.stage)?(v.stage===values.stage&&v.closed?v.closed:dateKey()):'';}
    if(kind==='leads')values.created=v.created||dateKey();
    if(kind==='tasks')values.done=v.done||false;
    if(id)Object.assign(item,values);else data[kind].push({id:crypto.randomUUID(),...values});
    log(`${id?'Memperbarui':'Menambahkan'} ${names[kind]}: ${values.name||values.title}`);$('#modal').close();save(`${names[kind][0].toUpperCase()+names[kind].slice(1)} berhasil ${id?'diperbarui':'ditambahkan'}.`);
  });
}
function confirmModal(title,text,callback){$('#modal').innerHTML=`<div class="modal-heading"><h2 id="modal-title">${esc(title)}</h2><button class="icon-btn" data-action="close" aria-label="Tutup">${icon('close')}</button></div><p class="confirm-text">${esc(text)}</p><div class="modal-actions"><button class="btn" data-action="close">Batal</button><button id="confirm" class="btn primary">Lanjutkan</button></div>`;if(!$('#modal').open)$('#modal').showModal();$('#confirm').addEventListener('click',()=>{$('#modal').close();callback();});}
function deleteItem(kind,id){if(kind==='contacts'&&(data.deals.some(d=>d.contact===id)||data.tasks.some(t=>t.contact===id))){toast('Kontak masih terkait deal atau tugas. Ubah atau hapus relasinya terlebih dahulu.');return;}confirmModal(`Hapus ${names[kind]}?`,'Data yang dihapus tidak bisa dikembalikan tanpa backup.',()=>{const item=data[kind].find(r=>r.id===id);data[kind]=data[kind].filter(r=>r.id!==id);log(`Menghapus ${names[kind]}: ${item.name||item.title}`);save('Data berhasil dihapus.');});}
function convertLead(id){const lead=data.leads.find(l=>l.id===id);if(!lead||lead.status==='Dikonversi')return;confirmModal('Konversikan lead menjadi kontak?','Kontak akan dibuat atau dicocokkan berdasarkan email. Setelah itu, Anda bisa mengisi penawaran dalam formulir deal.',()=>{let c=data.contacts.find(c=>lead.email&&c.email.toLowerCase()===lead.email.toLowerCase());if(!c){c={id:crypto.randomUUID(),name:lead.name,company:lead.company,email:lead.email,phone:'',role:''};data.contacts.push(c);}lead.status='Dikonversi';log(`Lead ${lead.name} dikonversi menjadi kontak`);save('Lead berhasil dikonversi. Lengkapi deal Anda.');openForm('deals',null,{contact:c.id,title:`Website ${lead.company||lead.name}`,notes:lead.notes});});}
function download(name,content,type){const url=URL.createObjectURL(new Blob([content],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('File ekspor telah disiapkan.');}
function exportCsv(){const cell=s=>{let v=String(s??'');if(/^[=+@\-\t\r]/.test(v))v="'"+v;return '"'+v.replace(/"/g,'""')+'"';};const rows=[['Nama','Perusahaan','Email','Telepon','Jabatan'],...data.contacts.filter(c=>matches(c.name,c.company,c.email)).map(c=>[c.name,c.company,c.email,c.phone,c.role])];download('crm-business-kontak.csv','\uFEFF'+rows.map(r=>r.map(cell).join(',')).join('\r\n'),'text/csv;charset=utf-8');}
$('#modal').addEventListener('click',e=>{if(e.target===$('#modal')){const r=$('#modal').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)$('#modal').close();}});
render();
